import React, { createContext, useContext, useState } from 'react';

// 1. Create the context
const WorkloadContext = createContext();

// 2. Create a custom hook for easy access to the context
export const useWorkload = () => {
    return useContext(WorkloadContext);
};

// 3. Create the Provider component
export const WorkloadProvider = ({ children }) => {
    // All the state that needs to be shared goes here
    const [baseAllocationValue, setBaseAllocationValue] = useState(0);
    const [perGroupAllocationValue, setPerGroupAllocationValue] = useState(0);
    const [perDeliveryAllocationValue, setPerDeliveryAllocationValue] = useState(0);
    const [perStudentAllocationValue, setPerStudentAllocationValue] = useState(0);
    const [activityAllocationValue, setActivityAllocationValue] = useState(0);
    const [numberOfStudents, setNumberOfStudents] = useState(100);

    // This is the state that was causing the problem
    const [deliveries, setDeliveries] = useState([
        { id: 1, deliveryLocation: 'CTN', lecturer: 'Mary', weeklyLectureTime: 2, earlyCareerLoading: 'No' },
        { id: 2, deliveryLocation: 'PEN', lecturer: 'Mary', weeklyLectureTime: 0, earlyCareerLoading: 'No' },
        { id: 3, deliveryLocation: 'KWD', lecturer: 'Mary', weeklyLectureTime: 0, earlyCareerLoading: 'No' },
    ]);

    // The value object holds all the state and functions to be shared
    const value = {
        baseAllocationValue, setBaseAllocationValue,
        perGroupAllocationValue, setPerGroupAllocationValue,
        perDeliveryAllocationValue, setPerDeliveryAllocationValue,
        perStudentAllocationValue, setPerStudentAllocationValue,
        activityAllocationValue, setActivityAllocationValue,
        numberOfStudents, setNumberOfStudents,
        deliveries, setDeliveries
    };

    return (
        <WorkloadContext.Provider value={value}>
            {children}
        </WorkloadContext.Provider>
    );
};
